WORD = {}
for item in WORD_RAW.split('|'):
    parts = item.strip().split(' ')
    if len(parts) >= 2:
        WORD[parts[0]] = parts[1].replace(',', '，')


def main():
    recs = json.load(io.open(BASE + '_parsed.json', encoding='utf-8'))
    optmap = json.load(io.open(BASE + '_optmap.json', encoding='utf-8'))
    gmap = optmap['分组']
    type_char = optmap['类型']['字']

    miss_word, miss_grp, out = [], set(), []
    pys = {}

    for r in recs:
        ch = r['char']
        # 拼音
        if ch not in pys:
            hs = pinyin(ch, style=Style.TONE, heteronym=True)[0]
            pys[ch] = hs[0]
        py = pys[ch]
        # 组词：Excel 优先
        w = r['words'].strip() if r['words'] else ''
        if not w:
            w = WORD.get(ch, '')
            if not w:
                miss_word.append(ch)
        else:
            w = w.replace(',', '，')
        # 分组
        gid = gmap.get(r['group'])
        if not gid:
            miss_grp.add(r['group'])
        props = {
            '字词': {'text': ch},
            '拼音': {'text': py},
            '启用': {'checkbox': True},
        }
        if w:
            props['组词'] = {'text': w}
        props['类型'] = {'select': type_char}
        if gid:
            props['分组'] = {'select': gid}
        out.append(props)

    print('生成记录:', len(out))
    print('缺组词:', len(miss_word), miss_word[:30])
    print('未知分组:', miss_grp or '无')
    with_num = len([x for x in out if '组词' in x])
    print('带组词记录:', with_num)
    io.open(BASE + '_seed_new.json', 'w', encoding='utf-8').write(
        json.dumps(out, ensure_ascii=False)
    )
    # 多音字清单（教材可能要改的）
    multi = [(c, pinyin(c, style=Style.TONE, heteronym=True)[0]) for c in sorted(pys)]
    hot = [x for x in multi if len(x[1]) > 1]
    io.open(BASE + '_multi.txt', 'w', encoding='utf-8').write(
        '\n'.join('%s %s' % (c, '/'.join(h)) for c, h in hot)
    )
    print('多音字(全部):', len(hot))


if __name__ == '__main__':
    main()
